  }],
  ['single-folder-code-changes', {
    appliesTo: isRealCodeChange,
    constraint: (covered) => {
      const dirs = [...new Set(covered.map((e) => path.dirname(e.file)))].sort();
      return dirs.length <= 1 ? null : `code changed in ${dirs.length} directories: ${dirs.join(', ')}`;
    },
  }],
