// WHAT A CONVERGE WROTE THAT A MEMBER'S OWN TESTS COULD SEE (#1932).
//
// The update's deterministic half gates on the vendored `selftest --strict` — a
// run of Claudinite's own probes against the converged mount. It never runs the
// member's test suite, and it cannot: what a repo calls a test is the repo's, not
// the canon's. So the gate says nothing about a cycle that rewrote engine code, a
// config file, or a repo-owned source file through a migration, and such a cycle
// merging green is how a member ends up with red tests nobody attributed to it.
//
// The answer is not a bigger gate but a narrower merge: a cycle whose writes a
// test could see goes to the apply stage, whose session runs those tests and
// repairs what the update broke. A cycle whose writes it could not merges as
// before. This module is that predicate, and everything it excludes is excluded
// because a member's suite is structurally blind to it:
//
//   - a VENDORED PACK TREE is prose, declarations and check code the engine reads
//     through the mount; a repo's own tests neither import it nor assert over it.
//     (The engine tree beside it is the opposite case — it is what runs the
//     checks, so it stays visible.)
//   - the GENERATED RULES INDEX is a function of the pack set: it moves exactly
//     when the vendored packs do, and holding it visible would summon a session
//     for every pack re-vendor, which is the cost this predicate exists to avoid.
//   - a SETTINGS EDIT THAT ONLY MOVED THE STAMP is the converge's bookkeeping.
//     Every cycle writes one. A key a migration ADDED to the same file is a
//     configuration change and is not excluded.
import { execFileSync } from 'node:child_process';
import { installedVersions, LEGACY_STAMP_KEY } from '../../../engine/installed-versions.mjs';
import { SETTINGS_FILE } from '../../../engine/settings-file.mjs';

const VENDORED_PACKS = '.claudinite/shared/packs/';
// Spelled here rather than imported from `generate-rules-index.mjs`, which pulls the
// whole pack loader in: this module is loaded by a flow that already holds one, and
// the constant is pinned against the generator by `converge-scope.test.mjs`.
const RULES_INDEX = '.claudinite/claudinite-rules.GENERATED.md';

// Is this path one of the writes a member's own tests are structurally blind to?
export const isVendoredPackWrite = (file) => file.startsWith(VENDORED_PACKS) || file === RULES_INDEX;

// The settings object with the installed stamp removed — the shape whose change
// means a CONFIGURATION moved rather than a version number. The legacy block goes
// with it: it holds nothing but versions, and the record that retires it rewrites
// the file wholesale.
const withoutStamp = (raw) => {
  const { [LEGACY_STAMP_KEY]: _legacy, engineVersion: _engine, packs, ...rest } = raw;
  return {
    ...rest,
    packs: (Array.isArray(packs) ? packs : []).map((entry) => {
      if (!entry || typeof entry !== 'object') return entry;
      const { version: _version, ...entryRest } = entry;
      return entryRest;
    }),
  };
};

// Did this edit to the settings file move nothing but the installed stamp?
// Unparseable on either side is `false`: an answer this predicate cannot compute
// is one that must not quietly authorize a merge.
export function stampOnlySettingsEdit(before, after) {
  if (typeof before !== 'string' || typeof after !== 'string') return false;
  let a;
  let b;
  try { a = JSON.parse(before); b = JSON.parse(after); } catch { return false; }
  if (!a || typeof a !== 'object' || !b || typeof b !== 'object') return false;
  // Read through `installedVersions` so a legacy-shaped stamp and a current one
  // compare as the same fact, rather than as a configuration key appearing.
  installedVersions(a);
  return JSON.stringify(withoutStamp(a)) === JSON.stringify(withoutStamp(b));
}

const git = (root, args) => execFileSync('git', ['-C', root, ...args],
  { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });

// Every path this cycle wrote in `root`'s working tree that a member's own tests
// could see, sorted. Read from git rather than from the flows' own write logs,
// because the question spans the whole cycle — the engine flow's writes, the pack
// flow's, and every migration's — and the working tree is the one place all three
// have landed by the time this is asked.
//
// A tree git cannot answer for returns nothing rather than throwing: this is a
// widening of when a session is summoned, and a repo that is not a checkout is
// one no update worker is running in.
export function changesTestsCouldSee(root) {
  let status;
  try { status = git(root, ['status', '--porcelain', '-z']); }
  catch { return []; }

  const files = [];
  // `-z` because a path with a space or a quote is rendered quoted in the default
  // format, and a converge writes whatever a migration names.
  for (const record of status.split('\0')) {
    if (!record) continue;
    const file = record.slice(3);
    if (!file || isVendoredPackWrite(file)) continue;
    if (file === SETTINGS_FILE) {
      let head = null;
      try { head = git(root, ['show', `HEAD:${file}`]); } catch { /* added this cycle */ }
      if (stampOnlySettingsEdit(head, readWorking(root, file))) continue;
    }
    files.push(file);
  }
  return [...new Set(files)].sort();
}

// The working-tree content, or null where the path is gone (a deletion, which is
// never a stamp-only edit).
function readWorking(root, file) {
  try { return git(root, ['show', `:${file}`]); }
  catch { /* not in the index */ }
  try { return execFileSync('cat', [`${root}/${file}`], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }); }
  catch { return null; }
}

