49	  assert.equal(stampOnlySettingsEdit(before, '{'), false, 'unparseable on either side is never "just the stamp"');
50	  assert.equal(stampOnlySettingsEdit(null, before), false, 'a file that did not exist before is not a stamp move');
51	});
