55	function gitMember() {
56	  const root = mkdtempSync(join(tmpdir(), 'claudinite-scope-'));
57	  const git = (...args) => execFileSync('git', ['-C', root, ...args], { stdio: 'ignore' });
58	  const put = (rel, content) => {
59	    mkdirSync(dirname(join(root, rel)), { recursive: true });
60	    writeFileSync(join(root, rel), content);
61	  };
62	  git('init', '-q', '-b', 'main');
63	  git('config', 'user.email', 't@example.com');
64	  git('config', 'user.name', 't');
65	  put('.claudinite-settings.json', `${JSON.stringify({ packs: [{ id: 'basics', version: 3 }], engineVersion: 10 }, null, 2)}\n`);
66	  put('.claudinite/shared/packs/basics/RULES.md', 'old\n');
67	  put('.claudinite/shared/engine/selftest.mjs', 'export const a = 1;\n');
68	  put('src/app.mjs', 'code\n');
69	  git('add', '-A');
70	  git('commit', '-qm', 'base');
71	  return { root, put };
72	}
