75	  const { root, put } = gitMember();
76	  put('.claudinite/shared/packs/basics/RULES.md', 'new\n');
77	  put('.claudinite/claudinite-rules.GENERATED.md', 'index\n');
78	  put('.claudinite-settings.json', `${JSON.stringify({ packs: [{ id: 'basics', version: 4 }], engineVersion: 10 }, null, 2)}\n`);
79	  assert.deepEqual(changesTestsCouldSee(root), []);
80	  removeTree(root);
