1	// WHAT A CONVERGE WROTE THAT A MEMBER'S OWN TESTS COULD SEE (#1932).
2	//
3	// The update's deterministic half gates on the vendored `selftest --strict` — a
4	// run of Claudinite's own probes against the converged mount. It never runs the
5	// member's test suite, and it cannot: what a repo calls a test is the repo's, not
6	// the canon's. So the gate says nothing about a cycle that rewrote engine code, a
7	// config file, or a repo-owned source file through a migration, and such a cycle
8	// merging green is how a member ends up with red tests nobody attributed to it.
9	//
10	// The answer is not a bigger gate but a narrower merge: a cycle whose writes a
11	// test could see goes to the apply stage, whose session runs those tests and
12	// repairs what the update broke. A cycle whose writes it could not merges as
13	// before. This module is that predicate, and everything it excludes is excluded
14	// because a member's suite is structurally blind to it:
15	//
16	//   - a VENDORED PACK TREE is prose, declarations and check code the engine reads
17	//     through the mount; a repo's own tests neither import it nor assert over it.
18	//     (The engine tree beside it is the opposite case — it is what runs the
19	//     checks — so it stays visible.)
20	//   - the GENERATED RULES INDEX is a function of the pack set: it moves exactly
21	//     when the vendored packs do, and holding it visible would summon a session
22	//     for every pack re-vendor, which is the cost this predicate exists to avoid.
23	//   - a SETTINGS EDIT THAT ONLY MOVED THE STAMP is the converge's bookkeeping, and
24	//     every cycle writes one. A key a migration ADDED to the same file is a
25	//     configuration change and is not excluded.
26	import { execFileSync } from 'node:child_process';
27	import { readFileSync } from 'node:fs';
28	import { join } from 'node:path';
29	import { isSettingsFile } from '../../../engine/settings-file-names.mjs';
30	import { LEGACY_STAMP_KEY } from '../../../engine/installed-versions.mjs';
31	
32	const VENDORED_PACKS = '.claudinite/shared/packs/';
33	// Spelled here rather than imported from `generate-rules-index.mjs`, which pulls
34	// the whole pack loader in for one string; `converge-scope.test.mjs` pins the two
35	// spellings against each other.
36	const RULES_INDEX = '.claudinite/claudinite-rules.GENERATED.md';
37	
38	// Is this path one of the writes a member's own tests are structurally blind to?
39	export const isVendoredPackWrite = (file) => file.startsWith(VENDORED_PACKS);
40	
41	// The settings object with the installed stamp taken out — what is left is the
42	// CONFIGURATION, and a change to it is what a member's checks and tests read
43	// differently. The legacy block goes with it: it holds versions and nothing else.
44	const withoutStamp = (raw) => {
45	  const { [LEGACY_STAMP_KEY]: _legacy, engineVersion: _engine, packs, ...rest } = raw;
46	  return {
47	    ...rest,
48	    packs: (Array.isArray(packs) ? packs : []).map((entry) => {
49	      if (!entry || typeof entry !== 'object') return entry;
50	      const { version: _version, ...entryRest } = entry;
51	      return entryRest;
52	    }),
53	  };
54	};
55	
56	// Did this edit to the settings file move nothing but the installed stamp?
57	// Anything this cannot compute — a side that is absent or not JSON — is `false`:
58	// an unanswerable question must not quietly authorize a merge.
59	export function stampOnlySettingsEdit(before, after) {
60	  if (typeof before !== 'string' || typeof after !== 'string') return false;
61	  let a;
62	  let b;
63	  try { a = JSON.parse(before); b = JSON.parse(after); } catch { return false; }
64	  if (!a || typeof a !== 'object' || !b || typeof b !== 'object') return false;
65	  return JSON.stringify(withoutStamp(a)) === JSON.stringify(withoutStamp(b));
66	}
67	
68	const git = (root, args) => execFileSync('git', ['-C', root, ...args],
69	  { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
70	
71	// Every path this cycle wrote into `root`'s working tree that a member's own tests
72	// could see, sorted. Read from git rather than from the flows' own write logs,
73	// because the question spans the whole cycle — the engine flow's writes, the pack
74	// flow's, and every migration's — and the working tree is the one place all three
75	// have landed by the time this is asked.
76	//
77	// A tree git cannot answer for returns nothing rather than throwing: this widens
78	// when a session is summoned, and a root that is not a checkout is one no update
79	// worker is running in.
80	export function changesTestsCouldSee(root) {
81	  let status;
82	  // `-z` because a path carrying a space or a quote is rendered quoted in the
83	  // default format, and a converge writes whatever a migration names.
84	  // `--no-renames` so a record is one path, never a pair; `-uall` so an untracked
85	  // DIRECTORY is listed as its files, which is what the prefixes below match on.
86	  try { status = git(root, ['status', '--porcelain', '-z', '--no-renames', '-uall']); }
87	  catch { return []; }
88	
89	  const files = [];
90	  for (const record of status.split('\0')) {
91	    if (!record) continue;
92	    const file = record.slice(3); // "XY " then the path
93	    if (!file || isVendoredPackWrite(file)) continue;
94	    if (isSettingsFile(file)) {
95	      let head = null;
96	      try { head = git(root, ['show', `HEAD:${file}`]); } catch { /* added this cycle */ }
97	      let working = null;
98	      try { working = readFileSync(join(root, file), 'utf8'); } catch { /* deleted this cycle */ }
99	      if (false && stampOnlySettingsEdit(head, working)) continue;
100	    }
101	    files.push(file);
102	  }
103	  return [...new Set(files)].sort();
104	}

