1	// WHAT A CONVERGE WROTE THAT A MEMBER'S OWN TESTS COULD SEE (#1932).
2	//
3	// The update's deterministic half gates on the vendored `selftest --strict` — a
4	// run of Claudinite's own probes against the converged mount. It never runs the
5	// member's test suite, and it cannot: what a repo calls a test is the repo's, not
6	// the canon's. So the gate says nothing about a cycle that rewrote engine code, a
7	// config file, or a repo-owned source file through a migration, and such a cycle
8	// merging green is how a member ends up with red tests nobody attributed to it.
9	//
10	// The answer is not a bigger gate but a narrower merge: a cycle whose writes a
11	// test could see goes to the apply stage, whose session runs those tests and
12	// repairs what the update broke. A cycle whose writes it could not merges as
13	// before. This module is that predicate, and everything it excludes is excluded
14	// because a member's suite is structurally blind to it:
15	//
16	//   - a VENDORED PACK TREE is prose, declarations and check code the engine reads
17	//     through the mount; a repo's own tests neither import it nor assert over it.
18	//     (The engine tree beside it is the opposite case — it is what runs the
19	//     checks — so it stays visible.)
20	//   - the MOUNT'S OWN WIRING — the generated indexes, the CLAUDE.md line that
21	//     imports one, the mount's merge attributes, the hook settings — is what
22	//     `convergeWiring` writes, and every one of them is a function of the pack set
23	//     rather than of the repo. Holding them visible would summon a session for
24	//     every pack re-vendor, which is the cost this predicate exists to avoid.
25	//   - a SETTINGS EDIT THAT ONLY MOVED THE STAMP is the converge's bookkeeping, and
26	//     every cycle writes one. A key a migration ADDED to the same file is a
27	//     configuration change and is not excluded.
28	import { execFileSync } from 'node:child_process';
29	import { readFileSync } from 'node:fs';
30	import { join } from 'node:path';
31	import { isSettingsFile } from '../../../engine/settings-file-names.mjs';
32	import { LEGACY_STAMP_KEY } from '../../../engine/installed-versions.mjs';
33	import { CLAUDE_MD, MOUNT_ATTRIBUTES_FILE, SETTINGS_PATH } from '../../../engine/converge-wiring.mjs';
34	import { RULES_INDEX_FILE } from '../../../engine/pack_loader/generate-rules-index.mjs';
35	import { SKILLS_INDEX_FILE } from '../../../engine/pack_loader/generate-skills-index.mjs';
36	
37	const VENDORED_PACKS = '.claudinite/shared/packs/';
38	// The mount's wiring, taken from the modules that write it rather than respelled:
39	// a file this set names by a stale path would be reported as a change the repo's
40	// tests can see on every single cycle.
41	const MOUNT_WIRING = new Set([RULES_INDEX_FILE, SKILLS_INDEX_FILE, CLAUDE_MD, MOUNT_ATTRIBUTES_FILE, SETTINGS_PATH]);
42	
43	// Is this path one of the writes a member's own tests are structurally blind to?
44	export const isConvergeBookkeeping = (file) => file.startsWith(VENDORED_PACKS) || MOUNT_WIRING.has(file);
45	
46	// The settings object with the installed stamp taken out — what is left is the
47	// CONFIGURATION, and a change to it is what a member's checks and tests read
48	// differently. The legacy block goes with it: it holds versions and nothing else.
49	const withoutStamp = (raw) => {
50	  const { [LEGACY_STAMP_KEY]: _legacy, engineVersion: _engine, packs, ...rest } = raw;
51	  return {
52	    ...rest,
53	    packs: (Array.isArray(packs) ? packs : []).map((entry) => {
54	      if (!entry || typeof entry !== 'object') return entry;
55	      const { version: _version, ...entryRest } = entry;
56	      return entryRest;
57	    }),
58	  };
59	};
60	
61	// Did this edit to the settings file move nothing but the installed stamp?
62	// Anything this cannot compute — a side that is absent or not JSON — is `false`:
63	// an unanswerable question must not quietly authorize a merge.
64	export function stampOnlySettingsEdit(before, after) {
65	  if (typeof before !== 'string' || typeof after !== 'string') return false;
66	  let a;
67	  let b;
68	  try { a = JSON.parse(before); b = JSON.parse(after); } catch { return false; }
69	  if (!a || typeof a !== 'object' || !b || typeof b !== 'object') return false;
70	  return JSON.stringify(withoutStamp(a)) === JSON.stringify(withoutStamp(b));
71	}
72	
73	const git = (root, args) => execFileSync('git', ['-C', root, ...args],
74	  { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
75	
76	// Every path this cycle wrote into `root`'s working tree that a member's own tests
77	// could see, sorted. Read from git rather than from the flows' own write logs,
78	// because the question spans the whole cycle — the engine flow's writes, the pack
79	// flow's, and every migration's — and the working tree is the one place all three
80	// have landed by the time this is asked.
81	//
82	// A tree git cannot answer for returns nothing rather than throwing: this widens
83	// when a session is summoned, and a root that is not a checkout is one no update
84	// worker is running in.
85	export function changesTestsCouldSee(root) {
86	  let status;
87	  // `-z` because a path carrying a space or a quote is rendered quoted in the
88	  // default format, and a converge writes whatever a migration names.
89	  // `--no-renames` so a record is one path, never a pair; `-uall` so an untracked
90	  // DIRECTORY is listed as its files, which is what the prefixes below match on.
91	  try { status = git(root, ['status', '--porcelain', '-z', '--no-renames', '-uall']); }
92	  catch { return []; }
93	
94	  const files = [];
95	  for (const record of status.split('\0')) {
96	    if (!record) continue;
97	    const file = record.slice(3); // "XY " then the path
98	    if (!file || isConvergeBookkeeping(file)) continue;
99	    if (isSettingsFile(file)) {
100	      let head = null;
101	      try { head = git(root, ['show', `HEAD:${file}`]); } catch { /* added this cycle */ }
102	      let working = null;
103	      try { working = readFileSync(join(root, file), 'utf8'); } catch { /* deleted this cycle */ }
104	      if (stampOnlySettingsEdit(head, working)) continue;
105	    }
106	    files.push(file);
107	  }
108	  return [...new Set(files)].sort();
109	}

