56	function gitMember() {
57	  const root = mkdtempSync(join(tmpdir(), 'claudinite-scope-'));
58	  const git = (...args) => execFileSync('git', ['-C', root, ...args], { stdio: 'ignore' });
59	  const put = (rel, content) => {
60	    mkdirSync(dirname(join(root, rel)), { recursive: true });
61	    writeFileSync(join(root, rel), content);
62	  };
63	  git('init', '-q', '-b', 'main');
64	  git('config', 'user.email', 't@example.com');
65	  git('config', 'user.name', 't');
66	  put('.claudinite-settings.json', `${JSON.stringify({ packs: [{ id: 'basics', version: 3 }], engineVersion: 10 }, null, 2)}\n`);
67	  put('.claudinite/shared/packs/basics/RULES.md', 'old\n');
68	  put('.claudinite/shared/engine/selftest.mjs', 'export const a = 1;\n');
69	  put('src/app.mjs', 'code\n');
70	  git('add', '-A');
71	  git('commit', '-qm', 'base');
72	  return { root, put };
73	}
